'use strict';
const WORK_GROUPS={done:{label:'Đã hoàn thành',color:'#3b8b61'},doing:{label:'Đang xây dựng',color:'#8054bf'},todo:{label:'Chưa làm',color:'#df8c40'},overdue:{label:'Quá hạn',color:'#cd4c58'}};
function workDeadline(t){return t.end?.slice(0,10)||t.due||'';}
function workCategory(t){return t.col==='Done'?'done':workDeadline(t)&&workDeadline(t)<today()?'overdue':t.col==='Doing'?'doing':'todo';}
function workGroupTasks(key){return allTasks().filter(t=>workCategory(t)===key);}
function workTaskList(tasks,limit=8){return tasks.slice(0,limit).map(t=>`<button type="button" class="work-task-row" data-task="${esc(t.id)}" data-pid="${esc(t.project.id)}"><strong>${esc(t.title)}</strong><small>${esc(t.project.name)} · ${taskPct(t)}%${workDeadline(t)?' · Hạn '+dateLabel(workDeadline(t)):' · Chưa đặt hạn'}</small></button>`).join('');}
function workChart(){const tasks=allTasks(),total=tasks.length,C=2*Math.PI*76;let offset=0;const circles=Object.entries(WORK_GROUPS).map(([key,g])=>{const count=tasks.filter(t=>workCategory(t)===key).length,length=total?count/total*C:0;const h=count?`<circle class="work-arc" data-work-group="${key}" role="button" tabindex="0" aria-label="${g.label}: ${count} việc, ${Math.round(count/total*100)}%" cx="110" cy="110" r="76" fill="none" stroke="${g.color}" stroke-width="28" stroke-dasharray="${length} ${C-length}" stroke-dashoffset="${-offset}" transform="rotate(-90 110 110)"/>`:'';offset+=length;return h;}).join('');return `<section class="panel chart-panel work-chart"><h3>Bức tranh công việc</h3><div class="work-chart-ring"><svg viewBox="0 0 220 220" role="group" aria-label="Phân bố công việc"><circle cx="110" cy="110" r="76" fill="none" stroke="#eee9f0" stroke-width="28"/>${circles}</svg><div class="work-chart-total"><strong>${total}</strong><span>Tổng công việc</span></div></div><div class="work-legend">${Object.entries(WORK_GROUPS).map(([key,g])=>`<button type="button" data-work-group="${key}" style="--group-color:${g.color}"><i class="dot"></i><span>${g.label}</span><strong>${tasks.filter(t=>workCategory(t)===key).length}</strong></button>`).join('')}</div><div class="work-group-detail" id="work-group-detail" aria-live="polite"><p>Rê chuột hoặc chạm vào từng màu để xem công việc.</p><small>Mỗi việc thuộc một nhóm. Việc trễ hạn được đưa vào nhóm đỏ cho đến khi hoàn tất.</small></div></section>`;}
const dashboardBeforeProjectUX=dashboard;dashboard=function(){return dashboardBeforeProjectUX().replace(/<section class="panel chart-panel">[\s\S]*?<\/section>/,workChart());};
function selectWorkGroup(key){const panel=$('.work-chart');if(!panel||panel.dataset.group===key)return;panel.dataset.group=key;panel.querySelectorAll('[data-work-group]').forEach(el=>{el.classList.toggle('is-selected',el.dataset.workGroup===key);el.classList.toggle('is-muted',el.dataset.workGroup!==key);});const tasks=workGroupTasks(key),g=WORK_GROUPS[key];$('#work-group-detail').innerHTML=`<div class="work-detail-heading" style="color:${g.color}"><strong>${g.label}</strong><span>${tasks.length} việc · ${allTasks().length?Math.round(tasks.length/allTasks().length*100):0}%</span></div><small>${new Set(tasks.map(t=>t.project.id)).size} dự án · ${tasks.filter(t=>['q1','q2'].includes(t.priority)).length} việc quan trọng</small><div class="work-detail-list">${workTaskList(tasks,4)||'<p>Chưa có công việc trong nhóm này.</p>'}</div>${tasks.length>4?`<button class="text-btn" type="button" data-work-all="${key}">Xem đủ ${tasks.length} công việc →</button>`:''}`;}
for(const event of ['pointerover','focusin'])document.addEventListener(event,e=>{const target=e.target.closest('[data-work-group]');if(target)selectWorkGroup(target.dataset.workGroup);});
document.addEventListener('click',e=>{const target=e.target.closest('[data-work-group]');if(target)selectWorkGroup(target.dataset.workGroup);const all=e.target.closest('[data-work-all]');if(all){const key=all.dataset.workAll;modal(`<h2>${esc(WORK_GROUPS[key].label)}</h2><div class="work-modal-list">${workTaskList(workGroupTasks(key),2000)}</div>`,null,true);}});
document.addEventListener('keydown',e=>{if(['Enter',' '].includes(e.key)&&e.target.matches('.work-arc')){e.preventDefault();selectWorkGroup(e.target.dataset.workGroup);}});
const PROJECT_ICONS={'Thiên nhiên':['🪷','🌱','🌿','🍃','🍀','🌲','🌳','🌵','🌸','🌼','🌻','🌷','🌺','🌊','⛰️','☀️','🌙','⭐','🐚','🦋','🐝','🕊️','🌈','🍄'],'Sáng tạo & công việc':['💡','🎨','🎬','📝','📚','📷','🎵','💻','📊','🧩','🧘','🏡','🛠️','🧭','🎯','🚀','📦','💼','🗓️','💎','🔬','🎓','❤️','☕'],'Họa tiết':['✳','✺','❋','✦','✧','◈','❀','☯','♧','◇','✿','☼','☾','⚘','⟡','❈']};
function colorToHSV(hex){const [r,g,b]=hex.match(/[a-f\d]{2}/gi).map(x=>parseInt(x,16)/255),max=Math.max(r,g,b),min=Math.min(r,g,b),d=max-min;let h=0;if(d)h=max===r?((g-b)/d+6)%6:max===g?(b-r)/d+2:(r-g)/d+4;return {h:h*60,s:max?d/max:0,v:max};}
function hsvToColor(h,s,v){const c=v*s,x=c*(1-Math.abs((h/60)%2-1)),m=v-c,values=h<60?[c,x,0]:h<120?[x,c,0]:h<180?[0,c,x]:h<240?[0,x,c]:h<300?[x,0,c]:[c,0,x],rgb=values.map(n=>Math.round((n+m)*255));return {rgb,hex:'#'+rgb.map(n=>n.toString(16).padStart(2,'0')).join('')};}
projectKeywordChoices=()=>'';
projectForm=function(p){if(!p&&data.projects.length>=100)return notify('Tối đa 100 dự án.');const initialColor=p?.color||COLORS[data.projects.length%6],initialIcon=p?.icon||'🌿';modal(`<h2>${p?'Chỉnh sửa dự án':'Một dự án mới bắt đầu'}</h2>${field('Tên dự án','name',p?.name||'','text',true,100)}<label class="field">Mô tả<textarea name="description" maxlength="2000">${esc(p?.description||'')}</textarea></label><div class="project-appearance"><details class="appearance-picker"><summary><span>Màu dự án</span><span class="appearance-value"><i id="project-color-swatch" style="background:${initialColor}"></i><b id="project-color-value">${initialColor.toUpperCase()}</b>⌄</span></summary><div class="color-picker-panel"><input type="hidden" name="color" value="${initialColor}"><div class="color-wheel-wrap"><canvas id="project-color-wheel" width="220" height="220" tabindex="0" role="slider" aria-label="Bánh xe màu. Trái phải đổi sắc, lên xuống đổi độ bão hòa." aria-valuemin="0" aria-valuemax="360"></canvas><i id="color-wheel-marker"></i></div><label>Độ sáng<input id="color-brightness" type="range" min="0" max="100" step="1"></label><label>HEX<input id="project-hex" maxlength="7" pattern="#[a-fA-F0-9]{6}" value="${initialColor}" spellcheck="false"></label><div class="rgb-inputs">${['R','G','B'].map((n,i)=>`<label>${n}<input type="number" id="project-rgb-${i}" min="0" max="255" step="1" aria-label="${n}"></label>`).join('')}</div><small id="project-rgb-code"></small></div></details><details class="appearance-picker"><summary><span>Biểu tượng</span><span class="appearance-value"><b id="project-icon-preview">${esc(initialIcon)}</b>Chọn biểu tượng ⌄</span></summary><input type="hidden" name="icon" value="${esc(initialIcon)}"><div class="icon-picker-panel">${Object.entries(PROJECT_ICONS).map(([group,icons])=>`<p>${group}</p><div class="icon-picker-grid">${icons.map(icon=>`<button type="button" data-pick-icon="${icon}" aria-label="Chọn ${icon}" aria-pressed="${icon===initialIcon}">${icon}</button>`).join('')}</div>`).join('')}</div></details></div>${p?'<button type="button" class="text-btn danger" data-action="delete-project">Xóa dự án này</button>':''}`,fd=>{const name=fd.get('name').trim(),color=fd.get('color'),icon=fd.get('icon');if(!name||!/^#[a-f\d]{6}$/i.test(color))return notify('Kiểm tra tên và mã màu.');if(p)Object.assign(p,{name,description:fd.get('description'),color,icon});else{p={id:uid(),keywords:[],name,description:fd.get('description'),color,icon,columns:[...COLS],tasks:[]};data.projects.push(p);}save();$('#editor').close();go('projects',p.id);notify('Đã lưu dự án.');});const form=$('#editor-form');form.querySelectorAll('[data-pick-icon]').forEach(button=>button.onclick=()=>{form.elements.icon.value=button.dataset.pickIcon;$('#project-icon-preview').textContent=button.dataset.pickIcon;form.querySelectorAll('[data-pick-icon]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));button.closest('details').open=false;});setupColorWheel(initialColor);};
function setupColorWheel(initial){let hsv=colorToHSV(initial);const canvas=$('#project-color-wheel'),ctx=canvas.getContext('2d'),size=canvas.width,radius=size/2,marker=$('#color-wheel-marker'),hex=$('#project-hex'),brightness=$('#color-brightness'),hidden=$('#editor-form').elements.color;function draw(){const pixels=ctx.createImageData(size,size);for(let y=0;y<size;y++)for(let x=0;x<size;x++){const dx=x-radius,dy=y-radius,s=Math.hypot(dx,dy)/radius,i=(y*size+x)*4;if(s>1)continue;const rgb=hsvToColor((Math.atan2(dy,dx)*180/Math.PI+360)%360,s,1).rgb;pixels.data.set([...rgb,255],i);}ctx.putImageData(pixels,0,0);}function update(){const color=hsvToColor(hsv.h,hsv.s,hsv.v);hidden.value=color.hex;hex.value=color.hex.toUpperCase();brightness.value=Math.round(hsv.v*100);color.rgb.forEach((n,i)=>$('#project-rgb-'+i).value=n);$('#project-rgb-code').textContent='rgb('+color.rgb.join(', ')+')';$('#project-color-swatch').style.background=color.hex;$('#project-color-value').textContent=color.hex.toUpperCase();marker.style.left=(50+Math.cos(hsv.h*Math.PI/180)*hsv.s*50)+'%';marker.style.top=(50+Math.sin(hsv.h*Math.PI/180)*hsv.s*50)+'%';canvas.style.filter='brightness('+hsv.v+')';canvas.setAttribute('aria-valuenow',String(Math.round(hsv.h)));canvas.setAttribute('aria-valuetext',color.hex);brightness.style.background='linear-gradient(to right,#000,'+hsvToColor(hsv.h,hsv.s,1).hex+')';}draw();update();function pick(e){const r=canvas.getBoundingClientRect(),dx=(e.clientX-r.left-r.width/2)/(r.width/2),dy=(e.clientY-r.top-r.height/2)/(r.height/2);hsv.h=(Math.atan2(dy,dx)*180/Math.PI+360)%360;hsv.s=Math.min(1,Math.hypot(dx,dy));update();}canvas.onpointerdown=e=>{canvas.setPointerCapture(e.pointerId);pick(e);};canvas.onpointermove=e=>{if(canvas.hasPointerCapture(e.pointerId))pick(e);};canvas.onkeydown=e=>{if(!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key))return;e.preventDefault();if(e.key==='ArrowLeft')hsv.h=(hsv.h+355)%360;if(e.key==='ArrowRight')hsv.h=(hsv.h+5)%360;if(e.key==='ArrowUp')hsv.s=Math.min(1,hsv.s+.05);if(e.key==='ArrowDown')hsv.s=Math.max(0,hsv.s-.05);update();};brightness.oninput=()=>{hsv.v=Number(brightness.value)/100;update();};hex.oninput=()=>{if(/^#[a-f\d]{6}$/i.test(hex.value)){hsv=colorToHSV(hex.value);update();}};for(let i=0;i<3;i++)$('#project-rgb-'+i).oninput=()=>{const rgb=[0,1,2].map(j=>$('#project-rgb-'+j).value);if(rgb.some(v=>v===''||!/^\d+$/.test(v)||Number(v)>255))return;hsv=colorToHSV('#'+rgb.map(n=>Number(n).toString(16).padStart(2,'0')).join(''));update();};}
// Acknowledging notices clears the current counter; due notices are renewed each day.
const priorNoticeSignature=noticeSignature;noticeSignature=t=>priorNoticeSignature(t)+(['Quá hạn','Sắp đến hạn'].includes(t.notice)?'|'+today():'');
let dueAlertLast=0,dueAlertOwner='';
function dueAlerts(){return taskNotices().filter(t=>['Quá hạn','Sắp đến hạn'].includes(t.notice));}
function refreshDueAlerts(){if(!currentUser||currentUser.repeat_alerts===0){$('#due-alert-strip')?.remove();return;}if(document.hidden)return;const tasks=dueAlerts();if(!tasks.length){$('#due-alert-strip')?.remove();return;}if(dueAlertOwner!==currentUser.id){dueAlertOwner=currentUser.id;dueAlertLast=0;}const late=tasks.filter(t=>t.notice==='Quá hạn').length,soon=tasks.length-late;if(!$('#due-alert-strip')&&Number(localRead('zen-alert-snooze:'+currentUser.id)||0)<Date.now())$('#main').insertAdjacentHTML('afterbegin',`<aside class="due-alert-strip" id="due-alert-strip"><span>${svgIcon('warning')}<strong>${late} việc quá hạn · ${soon} việc đến hạn trong 3 ngày</strong></span><div><button type="button" class="text-btn" data-open-due>Xem công việc</button><button type="button" class="text-btn" data-snooze-due>Ẩn 30 phút</button></div></aside>`);if(Date.now()-dueAlertLast>=3600000){dueAlertLast=Date.now();if(!$('#editor').open&&!document.querySelector('.welcome-dialog'))notify('Nhắc tiến độ: '+late+' việc quá hạn, '+soon+' việc sắp đến hạn.');}}
const renderBeforeProjectUX=render;render=function(){renderBeforeProjectUX();refreshDueAlerts();activateRequestedReminders();};
document.addEventListener('click',e=>{if(e.target.closest('[data-open-due]'))bell.click();if(e.target.closest('[data-snooze-due]')){localWrite('zen-alert-snooze:'+currentUser.id,String(Date.now()+30*60000));$('#due-alert-strip')?.remove();}});
setInterval(refreshDueAlerts,60000);
const accountPanelBeforeReports=accountPanel;accountPanel=function(){accountPanelBeforeReports();$('#email-reminder').nextElementSibling.textContent='Email hằng ngày: nhắc trước hạn 3 ngày, đến hạn hôm nay và quá hạn.';const days=$('#reminder-days');days.closest('label').innerHTML='<span>Tần suất</span><strong>Hằng ngày khi còn việc cần nhắc</strong><input type="hidden" id="reminder-days" value="1">';$('.reminder-options small').textContent='Giờ Việt Nam. Email liệt kê tên công việc, dự án và hạn hoàn thành. Dự án đã lưu trữ không được nhắc.';$('.reminder-options').insertAdjacentHTML('afterend',`<section class="profile-card weekly-settings"><h3>Tổng kết tuần</h3><p class="subtext">Tiến độ dự án và những việc nên ưu tiên cho tuần tới.</p><div class="report-setting-controls"><label class="settings-toggle"><input id="weekly-report-enabled" type="checkbox" ${currentUser.weekly_reports?'checked':''}><span>Email mỗi Chủ nhật</span></label><label class="report-hour">Giờ gửi<select id="weekly-report-hour" aria-label="Giờ gửi tổng kết Chủ nhật, giờ Việt Nam">${Array.from({length:24},(_,h)=>`<option value="${h}" ${h===(currentUser.weekly_hour??8)?'selected':''}>${String(h).padStart(2,'0')}:00</option>`).join('')}</select></label></div><label class="settings-toggle repeat-setting"><input id="repeat-due-alerts" type="checkbox" ${currentUser.repeat_alerts!==0?'checked':''}><span>Nhắc hạn trong ứng dụng<small>Nhắc lại mỗi giờ khi đang mở.</small></span></label><div class="help-actions"><button type="button" class="btn primary" id="save-weekly-settings">Lưu</button><button type="button" class="btn" id="preview-weekly-report">Xem báo cáo & PDF</button></div><p id="weekly-settings-status" role="status"></p></section>`);$('#save-weekly-settings').onclick=async e=>{e.target.disabled=true;try{const result=await requestAPI('preferences','PUT',{weeklyReports:$('#weekly-report-enabled').checked,weeklyHour:Number($('#weekly-report-hour').value),repeatAlerts:$('#repeat-due-alerts').checked});Object.assign(currentUser,result);refreshDueAlerts();$('#weekly-settings-status').textContent='Đã lưu. '+(result.weekly_reports?'Tổng kết được gửi mỗi Chủ nhật.':'Đã tắt email tổng kết.');}catch(err){$('#weekly-settings-status').textContent=err.message;}finally{e.target.disabled=false;}};$('#preview-weekly-report').onclick=()=>openWeeklyReport();};
// Update the existing Settings entry points to the enriched account panel.
accountButton.onclick=()=>{$('.sidebar').classList.remove('open');accountPanel();};document.querySelectorAll('.top-actions>.avatar').forEach(b=>b.onclick=accountPanel);

archivePage=function(){const projects=data.projects.filter(p=>p.archived);return heading('KHO LƯU TRỮ','Dự án tạm cất lại','Giữ nguyên trạng thái, checklist và tệp. Khôi phục để tiếp tục; dự án lưu trữ không được nhắc hạn.')+'<div class="archive-projects">'+(projects.map(p=>'<section class="panel"><h3>'+esc(p.icon)+' '+esc(p.name)+'</h3><p class="help-copy">'+p.tasks.filter(t=>t.col==='Done').length+'/'+p.tasks.length+' việc hoàn thành · '+progress(p.tasks).pct+'% tiến độ</p><div class="help-actions"><button class="btn" data-project="'+esc(p.id)+'">Xem dự án</button><button class="btn primary" data-project-archive="'+esc(p.id)+'">Khôi phục để làm tiếp</button></div></section>').join('')||'<p class="empty">Chưa có dự án lưu trữ.</p>')+'</div>';};
// Explicit activation link applies only to the account authenticated in this browser.
let notificationActivationAttempted=false;
async function activateRequestedReminders(){if(notificationActivationAttempted||!currentUser||new URLSearchParams(location.search).get('enable-notifications')!=='1')return;notificationActivationAttempted=true;const owner=currentUser.id;try{const preferences=await requestAPI('preferences','PUT',{emailReminders:true,days:1,weeklyReports:true,repeatAlerts:true});const url=new URL(location.href);url.searchParams.delete('enable-notifications');history.replaceState(null,'',url.pathname+url.search+url.hash);if(currentUser?.id===owner){Object.assign(currentUser,preferences);notify('Đã bật email nhắc hằng ngày và tổng kết Chủ nhật lúc '+String(preferences.weekly_hour).padStart(2,'0')+':00, giờ Việt Nam.');refreshDueAlerts();}}catch(e){notify('Chưa bật được thông báo: '+e.message+'. Tải lại trang để thử lại.');}}
